class StandardMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        best = None
        best_dist = float('inf')
        cr, cc = rows // 2, cols // 2
        for r in range(rows):
            for c in range(cols):
                dist = abs(r - cr) + abs(c - cc)
                if dist < best_dist:
                    best_dist = dist
                    best = (r, c)
        return ('reveal', best[0], best[1])

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        nbrs = neighbors_of.get((r, c), [])
        suspected = sum(
            1 for nr, nc in nbrs
            if (nr, nc) in mine_set or prob_map.get((nr, nc), 0.0) >= 0.5
        )
        revealed_neighbors = sum(
            1 for nr, nc in nbrs
            if grid[nr][nc].is_revealed
        )
        cascade_potential = len(nbrs) - suspected - revealed_neighbors
        return (p, -cascade_potential, suspected, self._rng.random())

class DriftingMineEarlyFlagAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        drift_prob = 0.30
        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            cell = grid[r][c]
            if cell.is_revealed or cell.is_flagged:
                adjusted[pos] = p
                continue
            neighbor_positions = neighbors_of.get(pos, [])
            revealed_neighbors = sum(
                1 for nr, nc in neighbor_positions
                if grid[nr][nc].is_revealed and not grid[nr][nc].is_mine
            )
            unrevealed_neighbors = sum(
                1 for nr, nc in neighbor_positions
                if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged
            )
            drift_in_chance = 0.0
            if unrevealed_neighbors > 0:
                for nr, nc in neighbor_positions:
                    ncell = grid[nr][nc]
                    if not ncell.is_revealed and not ncell.is_flagged:
                        neighbor_p = prob_map.get((nr, nc), 0.0)
                        neighbor_unrevealed = sum(
                            1 for nnr, nnc in neighbors_of.get((nr, nc), [])
                            if not grid[nnr][nnc].is_revealed and not grid[nnr][nnc].is_flagged
                        )
                        if neighbor_unrevealed > 1:
                            drift_in_chance += neighbor_p * drift_prob * (1.0 / neighbor_unrevealed)
            combined = p + (1.0 - p) * drift_in_chance
            combined = min(combined, 0.99)
            adjusted[pos] = combined
        return adjusted

