class RippleReveal(RevealStrategy):
    """
    Cascade reveal, but when a numbered cell is revealed it also temporarily
    exposes (for information only) how many of its neighbors are mines by
    'pinging' each unrevealed neighbor: if that neighbor has 0 adjacent mines,
    it gets revealed normally (like standard cascade). If it has >0 adjacent
    mines it stays hidden but the player benefits from the cascade stopping
    exactly there. The twist: if the clicked cell itself is a 0-cell, a standard
    BFS cascade runs. But if the clicked cell has adjacent mines > 0, we do a
    one-ring ripple — reveal the clicked cell, then also reveal all its
    unrevealed non-mine neighbors that are also numbered (adjacent_mines > 0),
    giving the player a richer information burst from a single click.
    This rewards skilled play: solvers can exploit the extra revealed numbers
    to chain-deduce, while random clickers gain little from scattered info.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]

        # If the target cell has no adjacent mines, do a full BFS cascade
        # (same as standard minesweeper cascade).
        if cell.adjacent_mines == 0:
            queue = deque([(r, c)])
            visited = {(r, c)}
            revealed = []

            while queue:
                cr, cc = queue.popleft()
                curr = board.grid[cr][cc]
                if curr.is_revealed or curr.is_flagged or curr.is_mine:
                    continue
                curr.is_revealed = True
                revealed.append((cr, cc))
                if curr.adjacent_mines == 0:
                    for nr, nc in board.neighbors(cr, cc):
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                else:
                    # Numbered border cell: also do the one-ring ripple from it
                    for nr, nc in board.neighbors(cr, cc):
                        if (nr, nc) not in visited:
                            nb = board.grid[nr][nc]
                            if not nb.is_revealed and not nb.is_flagged and not nb.is_mine:
                                if nb.adjacent_mines > 0:
                                    # Reveal this numbered neighbor too (ripple)
                                    visited.add((nr, nc))
                                    nb.is_revealed = True
                                    revealed.append((nr, nc))

            return revealed

        else:
            # Numbered cell: reveal it plus all unrevealed numbered (non-mine)
            # neighbors in one ripple burst.
            revealed = []
            cell.is_revealed = True
            revealed.append((r, c))

            for nr, nc in board.neighbors(r, c):
                nb = board.grid[nr][nc]
                if not nb.is_revealed and not nb.is_flagged and not nb.is_mine:
                    if nb.adjacent_mines > 0:
                        nb.is_revealed = True
                        revealed.append((nr, nc))
                    elif nb.adjacent_mines == 0:
                        # Zero neighbor: cascade from it
                        queue = deque([(nr, nc)])
                        visited = {(r, c), (nr, nc)}
                        while queue:
                            cr, cc = queue.popleft()
                            curr = board.grid[cr][cc]
                            if curr.is_revealed or curr.is_flagged or curr.is_mine:
                                continue
                            curr.is_revealed = True
                            revealed.append((cr, cc))
                            if curr.adjacent_mines == 0:
                                for nnr, nnc in board.neighbors(cr, cc):
                                    if (nnr, nnc) not in visited:
                                        visited.add((nnr, nnc))
                                        queue.append((nnr, nnc))
                            else:
                                for nnr, nnc in board.neighbors(cr, cc):
                                    if (nnr, nnc) not in visited:
                                        nnb = board.grid[nnr][nnc]
                                        if not nnb.is_revealed and not nnb.is_flagged and not nnb.is_mine:
                                            if nnb.adjacent_mines > 0:
                                                visited.add((nnr, nnc))
                                                nnb.is_revealed = True
                                                revealed.append((nnr, nnc))

            return revealed

