class RippleBurstPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        neighbors = neighbors_of.get((r, c), [])
        unrevealed_numbered_neighbors = sum(
            1
            for nr, nc in neighbors
            if not grid[nr][nc].is_revealed
            and not grid[nr][nc].is_flagged
            and (nr, nc) not in mine_set
            and prob_map.get((nr, nc), 0.5) < 0.5
            and any(
                grid[ar][ac].is_revealed and grid[ar][ac].adjacent_mines > 0
                for ar, ac in neighbors_of.get((nr, nc), [])
            )
        )
        ripple_bonus = -0.04 * unrevealed_numbered_neighbors
        adjusted_p = p + ripple_bonus
        return (adjusted_p, -unrevealed_numbered_neighbors, self._rng.random())

class ParityAwareMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        parity_constraints = []
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                true_count = cell.adjacent_mines
                parity = true_count % 2
                nbrs = neighbors_of.get((r, c), [])
                unknown_nbrs = [
                    (nr, nc) for nr, nc in nbrs
                    if not grid[nr][nc].is_revealed and (nr, nc) not in mine_set
                ]
                flagged_count = sum(
                    1 for nr, nc in nbrs
                    if grid[nr][nc].is_flagged or (nr, nc) in mine_set
                )
                if len(unknown_nbrs) == 0:
                    continue
                remaining_parity = (parity - (flagged_count % 2)) % 2
                parity_constraints.append((unknown_nbrs, remaining_parity))
        if not parity_constraints:
            return prob_map
        adjustment = {}
        for pos in prob_map:
            count_even = 0
            count_odd = 0
            for unknown_nbrs, remaining_parity in parity_constraints:
                if pos in unknown_nbrs:
                    if remaining_parity == 0:
                        count_even += 1
                    else:
                        count_odd += 1
            total = count_even + count_odd
            if total > 0:
                adjustment[pos] = (count_odd - count_even) / (2.0 * total)
        new_prob_map = {}
        for pos, p in prob_map.items():
            delta = adjustment.get(pos, 0.0)
            adjusted = p + 0.08 * delta
            adjusted = max(0.01, min(0.99, adjusted))
            new_prob_map[pos] = adjusted
        return new_prob_map

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        nbrs = neighbors_of.get((r, c), [])
        parity_neighbor_count = 0
        for nr, nc in nbrs:
            cell = grid[nr][nc]
            if cell.is_revealed and not cell.is_mine:
                true_count = cell.adjacent_mines
                parity = true_count % 2
                unknown_nbrs = [
                    (xr, xc) for xr, xc in neighbors_of.get((nr, nc), [])
                    if not grid[xr][xc].is_revealed and (xr, xc) not in mine_set
                ]
                if len(unknown_nbrs) > 0:
                    parity_neighbor_count += 1
        return (p - 0.03 * parity_neighbor_count, -parity_neighbor_count, self._rng.random())

class ZoneControlFocusedAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def _zone_of(self, r, c):
        return (r // 4, c // 4)

    def _zone_control_scores(self, game, grid, rows, cols):
        scores = {}
        num_zones_r = (rows + 3) // 4
        num_zones_c = (cols + 3) // 4
        for zri in range(num_zones_r):
            for zci in range(num_zones_c):
                r_start = zri * 4
                r_end = min(r_start + 4, rows)
                c_start = zci * 4
                c_end = min(c_start + 4, cols)
                safe_total = 0
                safe_revealed = 0
                for r in range(r_start, r_end):
                    for c in range(c_start, c_end):
                        cell = grid[r][c]
                        if not cell.is_mine:
                            safe_total += 1
                            if cell.is_revealed:
                                safe_revealed += 1
                if safe_total == 0:
                    frac = 1.0
                else:
                    frac = safe_revealed / safe_total
                scores[(zri, zci)] = frac
        return scores

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = game.get_config().rows
        cols = game.get_config().cols
        zone_scores = self._zone_control_scores(game, grid, rows, cols)
        zk = self._zone_of(r, c)
        zone_frac = zone_scores.get(zk, 0.5)
        zone_bonus = (1.0 - zone_frac) * 0.3
        adjusted_p = p - zone_bonus
        return (adjusted_p, self._rng.random())

