class ZoneControlWin(WinCondition):
    """
    The board is divided into overlapping 'corridors' — every row and every
    column is a zone. Win when a target fraction of zones are 'cleared',
    where a zone is cleared when at least clear_quota of its safe cells are
    revealed. Skilled solvers systematically clear rows/columns using
    deduction; random play scatters reveals without completing zones.
    """

    DEFAULT_ZONE_QUOTA = 0.80   # fraction of safe cells in a zone to clear it
    DEFAULT_WIN_QUOTA  = 0.65   # fraction of zones that must be cleared to win

    def __init__(self, seed=None, zone_quota=None, win_quota=None):
        super().__init__(seed)
        self.zone_quota = zone_quota if zone_quota is not None else self.DEFAULT_ZONE_QUOTA
        self.win_quota  = win_quota  if win_quota  is not None else self.DEFAULT_WIN_QUOTA

    def summary(self):
        return {"zone_quota": self.zone_quota, "win_quota": self.win_quota}

    def _zone_cleared(self, cells):
        safe_total    = sum(1 for c in cells if not c.is_mine)
        safe_revealed = sum(1 for c in cells if not c.is_mine and c.is_revealed)
        if safe_total == 0:
            return True   # a row/col with no safe cells is trivially cleared
        return safe_revealed / safe_total >= self.zone_quota

    def evaluate(self, board, game, action):
        rows = board.config.rows
        cols = board.config.cols
        total_zones   = rows + cols
        cleared_zones = 0

        # Check each row zone
        for r in range(rows):
            cells = [board.grid[r][c] for c in range(cols)]
            if self._zone_cleared(cells):
                cleared_zones += 1

        # Check each column zone
        for c in range(cols):
            cells = [board.grid[r][c] for r in range(rows)]
            if self._zone_cleared(cells):
                cleared_zones += 1

        if cleared_zones / total_zones >= self.win_quota:
            return 'won'
        return None

