class ZoneControlWinAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def _zone_progress(self, game, grid, rows, cols):
        row_progress = []
        col_progress = []
        for r in range(rows):
            safe_total = sum(1 for c in range(cols) if not game.get_cell(r, c).is_mine)
            safe_revealed = sum(1 for c in range(cols) if not game.get_cell(r, c).is_mine and game.get_cell(r, c).is_revealed)
            if safe_total == 0:
                row_progress.append(1.0)
            else:
                row_progress.append(safe_revealed / safe_total)
        for c in range(cols):
            safe_total = sum(1 for r in range(rows) if not game.get_cell(r, c).is_mine)
            safe_revealed = sum(1 for r in range(rows) if not game.get_cell(r, c).is_mine and game.get_cell(r, c).is_revealed)
            if safe_total == 0:
                col_progress.append(1.0)
            else:
                col_progress.append(safe_revealed / safe_total)
        return row_progress, col_progress

    def _zone_value(self, r, c, row_progress, col_progress):
        rp = row_progress[r]
        cp = col_progress[c]
        quota = 0.80
        row_gap = max(0.0, quota - rp)
        col_gap = max(0.0, quota - cp)
        row_near = 1.0 - abs(rp - quota) if rp < quota else 0.0
        col_near = 1.0 - abs(cp - quota) if cp < quota else 0.0
        return row_near + col_near - row_gap - col_gap

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = game.get_config().rows
        cols = game.get_config().cols
        row_progress, col_progress = self._zone_progress(game, grid, rows, cols)
        zone_val = self._zone_value(r, c, row_progress, col_progress)
        return (p, -zone_val, self._rng.random())

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        row_progress, col_progress = self._zone_progress(game, grid, rows, cols)
        quota = 0.80
        win_quota = 0.65
        total_zones = rows + cols
        cleared = sum(1 for r in range(rows) if row_progress[r] >= quota) + sum(1 for c in range(cols) if col_progress[c] >= quota)
        if cleared / total_zones >= win_quota:
            return prob_map
        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            rp = row_progress[r]
            cp = col_progress[c]
            row_near_threshold = (rp >= 0.5 and rp < quota)
            col_near_threshold = (cp >= 0.5 and cp < quota)
            if row_near_threshold or col_near_threshold:
                adjusted[pos] = p * 0.95
            else:
                adjusted[pos] = p
        return adjusted

class SplitClueReconstructionAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed:
            return None
        raw = cell.adjacent_mines
        if isinstance(raw, str):
            if not raw or raw.strip() == '':
                return 0
            if '/' in raw:
                parts = raw.split('/')
                try:
                    return int(parts[0]) + int(parts[1])
                except (ValueError, IndexError):
                    return None
            try:
                return int(raw)
            except ValueError:
                return None
        if raw is None:
            return 0
        return int(raw)

class DirectionalBearingMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def _bearing_neighbors(self, game, r, c, rows, cols, arrow_char):
        directions = {
            'N':  [(-1, 0), (-2, 0), (-1, -1), (-1, 1)],
            'S':  [(1, 0),  (2, 0),  (1, -1),  (1, 1)],
            'E':  [(0, 1),  (0, 2),  (-1, 1),  (1, 1)],
            'W':  [(0, -1), (0, -2), (-1, -1), (1, -1)],
            'NE': [(-1, 1), (-2, 2), (-1, 0),  (0, 1)],
            'NW': [(-1, -1),(-2, -2),(-1, 0),  (0, -1)],
            'SE': [(1, 1),  (2, 2),  (1, 0),   (0, 1)],
            'SW': [(1, -1), (2, -2), (1, 0),   (0, -1)],
        }
        offsets = directions.get(arrow_char, [])
        result = []
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc))
        return result

    def _parse_arrow(self, display_val):
        arrow_map = {
            8593: 'N', 8595: 'S', 8594: 'E', 8592: 'W',
            8599: 'NE', 8598: 'NW', 8600: 'SE', 8601: 'SW',
            '↑': 'N', '↓': 'S', '→': 'E', '←': 'W',
            '↗': 'NE', '↖': 'NW', '↘': 'SE', '↙': 'SW',
            'N': 'N', 'S': 'S', 'E': 'E', 'W': 'W',
            'NE': 'NE', 'NW': 'NW', 'SE': 'SE', 'SW': 'SW',
        }
        if display_val is None:
            return None
        return arrow_map.get(display_val, None)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        bearing_votes = {}
        bearing_counts = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                display = getattr(cell, 'display_value', None)
                if display is None:
                    display = getattr(cell, 'clue', None)
                arrow = self._parse_arrow(display)
                if arrow is None:
                    continue
                candidates = self._bearing_neighbors(game, r, c, rows, cols, arrow)
                unrevealed = [(nr, nc) for nr, nc in candidates
                              if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged]
                if not unrevealed:
                    continue
                weight = 1.0 / len(unrevealed)
                for pos in unrevealed:
                    bearing_votes[pos] = bearing_votes.get(pos, 0.0) + weight
                    bearing_counts[pos] = bearing_counts.get(pos, 0) + 1
        if not bearing_votes:
            return prob_map
        max_vote = max(bearing_votes.values()) if bearing_votes else 1.0
        new_map = dict(prob_map)
        for pos, votes in bearing_votes.items():
            if pos in mine_set:
                continue
            base = new_map.get(pos, 0.5)
            boost = 0.15 * (votes / max(max_vote, 1.0))
            new_map[pos] = min(0.95, base + boost)
        return new_map

class DriftingMinesPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        drift_prob = 0.30
        updated = {}
        for pos, p in prob_map.items():
            r, c = pos
            cell = grid[r][c]
            if cell.is_revealed or cell.is_flagged:
                updated[pos] = p
                continue
            neighbors = neighbors_of.get(pos, [])
            num_unrevealed_neighbors = sum(
                1 for nr, nc in neighbors
                if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged
            )
            drift_in_factor = drift_prob * num_unrevealed_neighbors / max(num_unrevealed_neighbors + 1, 1)
            adjusted = p * (1.0 - drift_prob) + (1.0 - p) * drift_in_factor * 0.15
            adjusted = max(0.0, min(1.0, adjusted))
            updated[pos] = adjusted
        return updated

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        neighbors = neighbors_of.get(pos, [])
        unflagged_mine_neighbors = sum(
            1 for nr, nc in neighbors
            if (nr, nc) in mine_set or prob_map.get((nr, nc), 0.0) >= 0.6
        )
        drift_penalty = 0.04 * unflagged_mine_neighbors
        score = p + drift_penalty
        return (score, unflagged_mine_neighbors, self._rng.random())

class NoisyCountMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        noisy_adjustments = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                true_count = cell.adjacent_mines
                nbrs = neighbors_of.get((r, c), [])
                unrevealed = [(nr, nc) for nr, nc in nbrs
                              if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged]
                flagged_count = sum(1 for nr, nc in nbrs if grid[nr][nc].is_flagged)
                known_mines = sum(1 for nr, nc in nbrs if (nr, nc) in mine_set)
                remaining_mines = true_count - flagged_count - known_mines
                if not unrevealed:
                    continue
                base_prob = remaining_mines / len(unrevealed)
                low_prob = max(0.0, (remaining_mines - 1) / len(unrevealed))
                high_prob = min(1.0, (remaining_mines + 1) / len(unrevealed))
                avg_prob = (low_prob + base_prob + high_prob) / 3.0
                for pos in unrevealed:
                    if pos not in noisy_adjustments:
                        noisy_adjustments[pos] = []
                    noisy_adjustments[pos].append(avg_prob)
        new_prob_map = dict(prob_map)
        for pos, estimates in noisy_adjustments.items():
            if pos in mine_set:
                continue
            if len(estimates) >= 2:
                averaged = sum(estimates) / len(estimates)
                original = prob_map.get(pos, 0.5)
                blended = 0.6 * averaged + 0.4 * original
                new_prob_map[pos] = max(0.05, min(0.95, blended))
        return new_prob_map

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        nbrs = neighbors_of.get((r, c), [])
        revealed_neighbor_count = sum(
            1 for nr, nc in nbrs
            if grid[nr][nc].is_revealed and not grid[nr][nc].is_mine
        )
        noise_confidence = min(1.0, revealed_neighbor_count / 3.0)
        adjusted_p = p * (1.0 - 0.1 * noise_confidence) + 0.5 * 0.1 * noise_confidence
        return (adjusted_p, -revealed_neighbor_count, self._rng.random())

class NoisyCountMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed or cell.is_mine:
            return None
        true_count = cell.adjacent_mines
        if true_count is None:
            return None
        return true_count

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        noise_rate = 0.20
        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            revealed_neighbors = [
                (nr, nc) for (nr, nc) in neighbors_of.get(pos, [])
                if grid[nr][nc].is_revealed and not grid[nr][nc].is_mine
            ]
            if not revealed_neighbors:
                adjusted[pos] = p
                continue
            estimates = []
            for nr, nc in revealed_neighbors:
                true_count = grid[nr][nc].adjacent_mines
                if true_count is None:
                    continue
                nb_neighbors = neighbors_of.get((nr, nc), [])
                nb_unrevealed = [
                    (xr, xc) for (xr, xc) in nb_neighbors
                    if not grid[xr][xc].is_revealed and (xr, xc) not in mine_set
                ]
                nb_flagged = sum(
                    1 for (xr, xc) in nb_neighbors
                    if (xr, xc) in mine_set
                )
                remaining = true_count - nb_flagged
                denom = len(nb_unrevealed)
                if denom > 0:
                    local_p = max(0.0, min(1.0, remaining / denom))
                    estimates.append(local_p)
            if not estimates:
                adjusted[pos] = p
                continue
            avg_estimate = sum(estimates) / len(estimates)
            variance = sum((e - avg_estimate) ** 2 for e in estimates) / len(estimates)
            uncertainty = min(1.0, variance * len(estimates) + noise_rate)
            blended = (1.0 - uncertainty) * avg_estimate + uncertainty * 0.5
            adjusted[pos] = blended
        return adjusted

class RankedNeighborMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed or cell.is_mine:
            return None
        raw = cell.adjacent_mines
        revealed_neighbors = [
            (nr, nc)
            for nr, nc in game.board.neighbors(r, c)
            if grid[nr][nc] == 'R'
        ]
        if not revealed_neighbors:
            return raw if raw > 0 else 0
        rank = raw
        neighbor_counts = []
        for nr, nc in revealed_neighbors:
            ncell = game.get_cell(nr, nc)
            if ncell.is_revealed and not ncell.is_mine:
                neighbor_counts.append(ncell.adjacent_mines)
        if not neighbor_counts:
            return raw if raw > 0 else 0
        all_vals = neighbor_counts + [rank]
        sorted_unique = sorted(set(all_vals))
        if rank < 1 or rank > len(sorted_unique):
            return None
        reconstructed = sorted_unique[rank - 1]
        return reconstructed

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        rank_map = {}
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_revealed and not cell.is_mine:
                    revealed_nbrs = [
                        (nr, nc)
                        for nr, nc in game.board.neighbors(r, c)
                        if game.get_cell(nr, nc).is_revealed and not game.get_cell(nr, nc).is_mine
                    ]
                    if revealed_nbrs:
                        my_count = cell.adjacent_mines
                        nbr_counts = [game.get_cell(nr, nc).adjacent_mines for nr, nc in revealed_nbrs]
                        all_vals = nbr_counts + [my_count]
                        sorted_unique = sorted(set(all_vals))
                        rank = sorted_unique.index(my_count) + 1
                        rank_map[(r, c)] = (rank, len(sorted_unique))
        adjusted = dict(prob_map)
        for pos in list(adjusted.keys()):
            r, c = pos
            unrevealed_revealed_nbrs = [
                (nr, nc)
                for nr, nc in game.board.neighbors(r, c)
                if game.get_cell(nr, nc).is_revealed and not game.get_cell(nr, nc).is_mine
                    and (nr, nc) in rank_map
            ]
            if not unrevealed_revealed_nbrs:
                continue
            low_rank_count = sum(
                1 for nbr in unrevealed_revealed_nbrs
                if rank_map[nbr][0] == 1
            )
            high_rank_count = sum(
                1 for nbr in unrevealed_revealed_nbrs
                if rank_map[nbr][0] == rank_map[nbr][1]
            )
            adjustment = 0.0
            if low_rank_count > 0:
                adjustment -= 0.04 * low_rank_count
            if high_rank_count > 0:
                adjustment += 0.04 * high_rank_count
            adjusted[pos] = max(0.0, min(1.0, adjusted[pos] + adjustment))
        return adjusted

