class ZoneControlFocusedAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def _zone_progress(self, game, grid, rows, cols):
        z = 4
        zone_rows = (rows + z - 1) // z
        zone_cols = (cols + z - 1) // z
        progress = {}
        for zr in range(zone_rows):
            for zc in range(zone_cols):
                r_start = zr * z
                r_end = min(r_start + z, rows)
                c_start = zc * z
                c_end = min(c_start + z, cols)
                safe_total = 0
                safe_revealed = 0
                for r in range(r_start, r_end):
                    for c in range(c_start, c_end):
                        cell = game.get_cell(r, c)
                        if not cell.is_mine:
                            safe_total += 1
                            if cell.is_revealed:
                                safe_revealed += 1
                if safe_total == 0:
                    ratio = 1.0
                else:
                    ratio = safe_revealed / safe_total
                progress[(zr, zc)] = ratio
        return progress

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = game.get_config().rows
        cols = game.get_config().cols
        z = 4
        zr = r // z
        zc = c // z
        zone_rows = (rows + z - 1) // z
        zone_cols = (cols + z - 1) // z
        total_zones = zone_rows * zone_cols
        progress = self._zone_progress(game, grid, rows, cols)
        controlled = sum(1 for v in progress.values() if v >= 0.75)
        zones_needed = int(total_zones * 0.70)
        zone_ratio = progress.get((zr, zc), 1.0)
        if controlled >= zones_needed:
            zone_bonus = 0.0
        else:
            zone_bonus = -0.15 * (1.0 - zone_ratio)
        return (p + zone_bonus, self._rng.random())

class QuadrantSplitClueAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed or cell.is_mine:
            return None
        raw = cell.adjacent_mines
        if raw is None:
            return 0
        if isinstance(raw, int):
            return raw
        s = str(raw).strip()
        if not s:
            return 0
        if '/' in s:
            parts = s.split('/')
            try:
                return int(parts[0]) + int(parts[1])
            except (ValueError, IndexError):
                return 0
        try:
            return int(s)
        except ValueError:
            return 0

