class RippleReveal(RevealStrategy):
    """
    Cascade reveal with a bonus: after the standard BFS flood-fill completes,
    any already-revealed numbered cell whose mine count exactly equals its
    number of flagged neighbors automatically reveals all its non-flagged,
    non-mine, unrevealed neighbors (a 'chord'). This compounds the information
    advantage of skilled play — solvers who flag correctly unlock free reveals,
    while random play rarely satisfies the chord condition and gains nothing.
    The chording is applied iteratively until no new chords trigger.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        # Step 1: Standard cascade BFS from (r, c)
        newly_revealed: list[tuple[int, int]] = []
        visited: set[tuple[int, int]] = set()

        cell = board.grid[r][c]
        if cell.is_mine or cell.is_revealed or cell.is_flagged:
            return newly_revealed

        if cell.adjacent_mines > 0:
            cell.is_revealed = True
            newly_revealed.append((r, c))
        else:
            queue: deque[tuple[int, int]] = deque([(r, c)])
            visited.add((r, c))
            while queue:
                cr, cc = queue.popleft()
                curr = board.grid[cr][cc]
                if curr.is_revealed or curr.is_flagged or curr.is_mine:
                    continue
                curr.is_revealed = True
                newly_revealed.append((cr, cc))
                if curr.adjacent_mines == 0:
                    for nr, nc in board.neighbors(cr, cc):
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

        # Step 2: Iterative chord pass over all revealed numbered cells
        # A chord fires when flagged_neighbors == adjacent_mines for a revealed cell
        changed = True
        chord_visited: set[tuple[int, int]] = set()
        while changed:
            changed = False
            for row in range(board.config.rows):
                for col in range(board.config.cols):
                    c_cell = board.grid[row][col]
                    if not c_cell.is_revealed or c_cell.is_mine:
                        continue
                    if c_cell.adjacent_mines == 0:
                        continue
                    neighbors = board.neighbors(row, col)
                    flagged_count = sum(
                        1 for nr, nc in neighbors if board.grid[nr][nc].is_flagged
                    )
                    if flagged_count != c_cell.adjacent_mines:
                        continue
                    # Chord: reveal all unrevealed, unflagged, non-mine neighbors
                    for nr, nc in neighbors:
                        n_cell = board.grid[nr][nc]
                        if n_cell.is_revealed or n_cell.is_flagged or n_cell.is_mine:
                            continue
                        if (nr, nc) in chord_visited:
                            continue
                        chord_visited.add((nr, nc))
                        # Cascade from this cell if it's a zero
                        if n_cell.adjacent_mines == 0:
                            sub_queue: deque[tuple[int, int]] = deque([(nr, nc)])
                            sub_visited: set[tuple[int, int]] = {(nr, nc)}
                            while sub_queue:
                                sr, sc = sub_queue.popleft()
                                s_cell = board.grid[sr][sc]
                                if s_cell.is_revealed or s_cell.is_flagged or s_cell.is_mine:
                                    continue
                                s_cell.is_revealed = True
                                newly_revealed.append((sr, sc))
                                chord_visited.add((sr, sc))
                                changed = True
                                if s_cell.adjacent_mines == 0:
                                    for snr, snc in board.neighbors(sr, sc):
                                        if (snr, snc) not in sub_visited:
                                            sub_visited.add((snr, snc))
                                            sub_queue.append((snr, snc))
                        else:
                            n_cell.is_revealed = True
                            newly_revealed.append((nr, nc))
                            changed = True

        return newly_revealed

