class ChainReactionClusterAwarePAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def _estimate_cluster_size(self, pos, prob_map, mine_set, neighbors_of, visited=None):
        if visited is None:
            visited = set()
        if pos in visited:
            return 0
        visited.add(pos)
        r, c = pos
        size = 1
        for nr, nc in neighbors_of.get((r, c), []):
            npos = (nr, nc)
            if npos not in visited:
                if npos in mine_set or prob_map.get(npos, 0.0) >= 0.5:
                    size += self._estimate_cluster_size(npos, prob_map, mine_set, neighbors_of, visited)
        return size

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        neighbor_mine_count = sum(
            1
            for nr, nc in neighbors_of.get((r, c), [])
            if (nr, nc) in mine_set or prob_map.get((nr, nc), 0.0) >= 0.5
        )
        cluster_size = 0
        if p >= 0.3 or neighbor_mine_count > 0:
            cluster_size = self._estimate_cluster_size(pos, prob_map, mine_set, neighbors_of)
        chain_penalty = p * (1 + 0.15 * cluster_size)
        return (chain_penalty + 0.05 * neighbor_mine_count, -neighbor_mine_count, self._rng.random())

