            return None
        raw = cell.adjacent_mines
        neighbors = game.board.neighbors(r, c)
        flagged = sum(1 for nr, nc in neighbors if grid[nr][nc].is_flagged)
        unrevealed = sum(1 for nr, nc in neighbors if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged)
        low = max(0, raw - 1)
        high = raw + 1
        adjusted_mines = raw - flagged
        low_adj = max(0, low - flagged)
        high_adj = max(0, high - flagged)
        if unrevealed == 0:
            return raw
        if high_adj <= 0:
            return 0
        if low_adj >= unrevealed:
            return unrevealed
        return raw

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        neighbor_mine_counts = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                raw = cell.adjacent_mines
                neighbors = neighbors_of.get((r, c), [])
                flagged = sum(1 for nr, nc in neighbors if grid[nr][nc].is_flagged)
                unrevealed = [(nr, nc) for nr, nc in neighbors if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged]
                if not unrevealed:
                    continue
                low_remaining = max(0, (raw - 1) - flagged)
                high_remaining = max(0, (raw + 1) - flagged)
                n = len(unrevealed)
                if high_remaining <= 0:
                    for pos in unrevealed:
                        if pos not in mine_set:
                            neighbor_mine_counts[pos] = neighbor_mine_counts.get(pos, []) + [0.0]
                elif low_remaining >= n:
                    for pos in unrevealed:
                        if pos not in mine_set:
                            neighbor_mine_counts[pos] = neighbor_mine_counts.get(pos, []) + [1.0]
                else:
                    mid = raw - flagged
                    p = max(0.0, min(1.0, mid / n))
                    for pos in unrevealed:
                        neighbor_mine_counts[pos] = neighbor_mine_counts.get(pos, []) + [p]
        new_prob_map = dict(prob_map)
        for pos, votes in neighbor_mine_counts.items():
            if pos in mine_set:
                continue
            if len(votes) >= 2:
                avg = sum(votes) / len(votes)
                existing = new_prob_map.get(pos, 0.5)
                blended = 0.6 * avg + 0.4 * existing
                new_prob_map[pos] = blended
        return new_prob_map

