class ProgressiveZoneWin(WinCondition):
    """
    The board is divided into 4 quadrant zones. The player must clear each
    zone sequentially: a zone is 'cleared' when at least ZONE_QUOTA fraction
    of its safe cells are revealed. Only after clearing zone 1 does zone 2
    unlock (and so on). The win condition is met when all 4 zones are cleared
    in order. This rewards skilled solvers who can efficiently deduce safe
    cells in constrained regions while random play wastes clicks across the
    board instead of focusing on the active zone.
    """

    ZONE_QUOTA = 0.75
    NUM_ZONES = 4

    def __init__(self, seed=None):
        super().__init__(seed)
        self.quota = self.ZONE_QUOTA

    def _get_zone(self, r, c, rows, cols):
        mid_r = rows // 2
        mid_c = cols // 2
        if r < mid_r and c < mid_c:
            return 0
        elif r < mid_r and c >= mid_c:
            return 1
        elif r >= mid_r and c < mid_c:
            return 2
        else:
            return 3

    def _zone_progress(self, board, zone_id):
        rows = board.config.rows
        cols = board.config.cols
        total_safe = 0
        revealed_safe = 0
        for r in range(rows):
            for c in range(cols):
                cell = board.grid[r][c]
                if self._get_zone(r, c, rows, cols) != zone_id:
                    continue
                if not cell.is_mine:
                    total_safe += 1
                    if cell.is_revealed:
                        revealed_safe += 1
        if total_safe == 0:
            return 1.0
        return revealed_safe / total_safe

    def evaluate(self, board, game, action):
        rows = board.config.rows
        cols = board.config.cols
        # Check zones in order; all must reach quota
        for zone_id in range(self.NUM_ZONES):
            progress = self._zone_progress(board, zone_id)
            if progress < self.quota:
                # This zone not yet cleared — game continues
                return None
        # All zones cleared in sequence (since we check 0->3 and return None on first failure)
        return 'won'

    def summary(self):
        return {'quota': self.quota, 'num_zones': self.NUM_ZONES}

