class QuadrantFocusedMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def _get_zone(self, r, c, rows, cols):
        mid_r = rows // 2
        mid_c = cols // 2
        if r < mid_r and c < mid_c:
            return 0
        elif r < mid_r and c >= mid_c:
            return 1
        elif r >= mid_r and c < mid_c:
            return 2
        else:
            return 3

    def _zone_progress(self, game, zone_id):
        rows = game.get_config().rows
        cols = game.get_config().cols
        total_safe = 0
        revealed_safe = 0
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if self._get_zone(r, c, rows, cols) != zone_id:
                    continue
                if not cell.is_mine:
                    total_safe += 1
                    if cell.is_revealed:
                        revealed_safe += 1
        if total_safe == 0:
            return 1.0
        return revealed_safe / total_safe

    def _target_zone(self, game):
        for zone_id in range(4):
            if self._zone_progress(game, zone_id) < 0.75:
                return zone_id
        return 0

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows = game.get_config().rows
        cols = game.get_config().cols
        p = prob_map.get(pos, 0.5)
        target_zone = self._target_zone(game)
        cell_zone = self._get_zone(r, c, rows, cols)
        zone_bonus = 0.0 if cell_zone == target_zone else 0.3
        return (p + zone_bonus, self._rng.random())

    def opening_action(self, game, grid, rows, cols):
        mid_r = rows // 2
        mid_c = cols // 2
        candidates = [
            (mid_r // 2, mid_c // 2),
            (mid_r // 2, mid_c // 2 + 1),
            (mid_r // 2 + 1, mid_c // 2),
        ]
        for r, c in candidates:
            if 0 <= r < rows and 0 <= c < cols:
                cell = game.get_cell(r, c)
                if not cell.is_revealed and not cell.is_flagged:
                    return ("reveal", r, c)
        return ("reveal", rows // 4, cols // 4)

