                if cell.is_revealed and not cell.is_mine:
                    noisy_neighbors.append((nr, nc))
            if noisy_neighbors:
                uncertainty_boost = noise_prob * (1.0 - abs(2.0 * p - 1.0))
                new_p = p * (1.0 - uncertainty_boost) + 0.5 * uncertainty_boost
                adjusted[pos] = max(0.0, min(1.0, new_p))
            else:
                adjusted[pos] = p
        return adjusted

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
