class SegmentedCountInfo(InfoStrategy):
    """
    Each revealed cell shows two numbers separated by '/':
      - Left: count of mines among its TOP and LEFT neighbors (NW, N, NE, W)
      - Right: count of mines among its BOTTOM and RIGHT neighbors (E, SW, S, SE)
    The skilled solver can reconstruct the total by summing, but more importantly
    can use the directional split to triangulate which half of the neighborhood
    contains mines — providing richer spatial deduction than a single count.
    A cell showing '0/0' renders blank for cleanliness.
    """

    def encode(self, board, r, c):
        # Define the two halves by relative offset
        # Top-left half: NW(-1,-1), N(-1,0), NE(-1,+1), W(0,-1)
        top_left_offsets = {(-1, -1), (-1, 0), (-1, 1), (0, -1)}
        # Bottom-right half: E(0,+1), SW(+1,-1), S(+1,0), SE(+1,+1)
        bottom_right_offsets = {(0, 1), (1, -1), (1, 0), (1, 1)}

        top_left_count = 0
        bottom_right_count = 0

        for nr, nc in board.neighbors(r, c):
            dr = nr - r
            dc = nc - c
            cell = board.grid[nr][nc]
            if cell.is_mine:
                if (dr, dc) in top_left_offsets:
                    top_left_count += 1
                elif (dr, dc) in bottom_right_offsets:
                    bottom_right_count += 1

        if top_left_count == 0 and bottom_right_count == 0:
            return ""
        return str(top_left_count) + "/" + str(bottom_right_count)

