class DirectionalClueAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)
        self._tl_counts = {}
        self._br_counts = {}

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed:
            return None
        raw = None
        try:
            raw = str(cell.adjacent_mines)
        except Exception:
            return None
        if raw is None:
            return None
        if '/' in raw:
            parts = raw.split('/')
            if len(parts) == 2:
                try:
                    tl = int(parts[0].strip())
                    br = int(parts[1].strip())
                    self._tl_counts[(r, c)] = tl
                    self._br_counts[(r, c)] = br
                    return tl + br
                except ValueError:
                    return 0
            return 0
        if raw == '' or raw is None:
            return 0
        try:
            return int(raw)
        except (ValueError, TypeError):
            return 0

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        tl_offsets = {(-1, -1), (-1, 0), (-1, 1), (0, -1)}
        br_offsets = {(0, 1), (1, -1), (1, 0), (1, 1)}
        updates = {}
        for (r, c), tl in self._tl_counts.items():
            br = self._br_counts.get((r, c), 0)
            tl_unknowns = []
            br_unknowns = []
            tl_known_mines = 0
            br_known_mines = 0
            for nr, nc in neighbors_of.get((r, c), []):
                dr = nr - r
                dc = nc - c
                cell = game.get_cell(nr, nc)
                if (dr, dc) in tl_offsets:
                    if (nr, nc) in mine_set:
                        tl_known_mines += 1
                    elif not cell.is_revealed and not cell.is_flagged:
                        tl_unknowns.append((nr, nc))
                elif (dr, dc) in br_offsets:
                    if (nr, nc) in mine_set:
                        br_known_mines += 1
                    elif not cell.is_revealed and not cell.is_flagged:
                        br_unknowns.append((nr, nc))
            tl_remaining = tl - tl_known_mines
            br_remaining = br - br_known_mines
            if tl_remaining >= 0 and len(tl_unknowns) > 0:
                if tl_remaining == 0:
                    for pos in tl_unknowns:
                        updates[pos] = min(updates.get(pos, 1.0), 0.0)
                elif tl_remaining == len(tl_unknowns):
                    for pos in tl_unknowns:
                        updates[pos] = max(updates.get(pos, 0.0), 1.0)
                else:
                    p = tl_remaining / len(tl_unknowns)
                    for pos in tl_unknowns:
                        if pos not in updates:
                            updates[pos] = p
                        else:
                            updates[pos] = (updates[pos] + p) / 2.0
            if br_remaining >= 0 and len(br_unknowns) > 0:
                if br_remaining == 0:
                    for pos in br_unknowns:
                        updates[pos] = min(updates.get(pos, 1.0), 0.0)
                elif br_remaining == len(br_unknowns):
                    for pos in br_unknowns:
                        updates[pos] = max(updates.get(pos, 0.0), 1.0)
                else:
                    p = br_remaining / len(br_unknowns)
                    for pos in br_unknowns:
                        if pos not in updates:
                            updates[pos] = p
                        else:
                            updates[pos] = (updates[pos] + p) / 2.0
        for pos, val in updates.items():
            if val == 0.0:
                prob_map[pos] = 0.0
            elif val == 1.0:
                prob_map[pos] = 1.0
            elif pos in prob_map:
                prob_map[pos] = (prob_map[pos] + val) / 2.0
            else:
                prob_map[pos] = val
        return prob_map

