class QuadrantSplitInfo(InfoStrategy):
    """
    Each revealed cell shows mine counts split into two pairs of diagonal quadrants:
    'NW+SE / NE+SW' — the count of mines in the NW+SE neighbors vs the NE+SW neighbors.
    This gives skilled solvers two independent linear constraints per cell to triangulate
    mine positions, while random play cannot exploit the cross-diagonal spatial signal.
    """

    def encode(self, board, r, c):
        nw_se = 0
        ne_sw = 0
        for nr, nc in board.neighbors(r, c):
            if not board.grid[nr][nc].is_mine:
                continue
            dr = nr - r
            dc = nc - c
            # NW quadrant: dr<0, dc<0 or dr>0, dc>0 => SE
            # NE quadrant: dr<0, dc>0 or dr>0, dc<0 => SW
            # Cardinal (dr==0 or dc==0): split evenly by assigning to nw_se if dr+dc<=0 else ne_sw
            if dr == 0 and dc == 0:
                continue
            if dr == 0:
                # pure E or W
                if dc < 0:
                    nw_se += 1  # W -> NW+SE group
                else:
                    ne_sw += 1  # E -> NE+SW group
            elif dc == 0:
                # pure N or S
                if dr < 0:
                    nw_se += 1  # N -> NW+SE group
                else:
                    ne_sw += 1  # S -> NE+SW group
            else:
                # diagonal
                if dr * dc > 0:
                    # same sign => NW (dr<0,dc<0) or SE (dr>0,dc>0)
                    nw_se += 1
                else:
                    # opposite sign => NE (dr<0,dc>0) or SW (dr>0,dc<0)
                    ne_sw += 1
        total = nw_se + ne_sw
        if total == 0:
            return ""
        return str(nw_se) + "/" + str(ne_sw)

