        if raw is None:
            raw = getattr(cell, 'label', None)
        if isinstance(raw, str) and '/' in raw:
            parts = raw.split('/')
            if len(parts) == 2:
                try:
                    a = int(parts[0].strip())
                    b = int(parts[1].strip())
                    return a + b
                except ValueError:
                    pass
        if isinstance(raw, str) and raw == '':
            return 0
        if isinstance(raw, int):
            return raw
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
