                    continue
                raw = getattr(cell, 'display', None)
                if raw is None:
                    raw = getattr(cell, 'clue', None)
                if raw is None:
                    raw = getattr(cell, 'label', None)
                if not (isinstance(raw, str) and '/' in raw):
                    continue
                parts = raw.split('/')
                if len(parts) != 2:
                    continue
                try:
                    a = int(parts[0].strip())
                    b = int(parts[1].strip())
                except ValueError:
                    continue
                neighbors = neighbors_of.get((r, c), [])
                nw_se_neighbors = []
                ne_sw_neighbors = []
                for nr, nc in neighbors:
                    if game.get_cell(nr, nc).is_revealed:
                        continue
                    dr = nr - r
                    dc = nc - c
                    if dr == 0 and dc == 0:
                        continue
                    if dr == 0:
                        if dc < 0:
                            nw_se_neighbors.append((nr, nc))
                        else:
                            ne_sw_neighbors.append((nr, nc))
                    elif dc == 0:
                        if dr < 0:
                            nw_se_neighbors.append((nr, nc))
                        else:
                            ne_sw_neighbors.append((nr, nc))
