                nw_se_flagged = sum(1 for pos in nw_se_neighbors if pos in mine_set)
                ne_sw_flagged = sum(1 for pos in ne_sw_neighbors if pos in mine_set)
                nw_se_unknown = [pos for pos in nw_se_neighbors if pos not in mine_set]
                ne_sw_unknown = [pos for pos in ne_sw_neighbors if pos not in mine_set]
                nw_se_remaining = a - nw_se_flagged
                ne_sw_remaining = b - ne_sw_flagged
                if nw_se_remaining >= 0 and len(nw_se_unknown) > 0:
                    if nw_se_remaining == 0:
                        for pos in nw_se_unknown:
