                    elif ne_sw_remaining == len(ne_sw_unknown):
                        for pos in ne_sw_unknown:
                            prob_map[pos] = max(prob_map.get(pos, 0.0), 1.0)
                    else:
                        p = ne_sw_remaining / len(ne_sw_unknown)
                        for pos in ne_sw_unknown:
                            if pos not in mine_set and prob_map.get(pos, -1) < 0:
                                prob_map[pos] = p
