class ChebyshevDistanceAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed or cell.is_mine:
            return None
        dist = cell.adjacent_mines
        if dist == 1:
            return 1
        return 0

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        dist_map = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed and not cell.is_mine:
                    dist_map[(r, c)] = cell.adjacent_mines

        updated = dict(prob_map)

        for pos in list(updated.keys()):
            if pos in mine_set:
                continue
            pr, pc = pos
            cell = grid[pr][pc]
            if cell.is_revealed or cell.is_flagged:
                continue

            min_dist_from_revealed = None
            for (dr, dc), d in dist_map.items():
                cheby = max(abs(pr - dr), abs(pc - dc))
                if min_dist_from_revealed is None or cheby < min_dist_from_revealed:
                    min_dist_from_revealed = cheby

            if min_dist_from_revealed is None:
                continue

            current_p = updated[pos]

            must_have_mine_within = {}
            for (dr, dc), d in dist_map.items():
                if d == 0:
                    cheby = max(abs(pr - dr), abs(pc - dc))
                    if cheby == 0:
                        updated[pos] = 0.0
                        break

            if updated[pos] == 0.0:
                continue

            penalty = 0.0
            bonus = 0.0
            for (dr, dc), d in dist_map.items():
                cheby = max(abs(pr - dr), abs(pc - dc))
                if d == 1 and cheby == 1:
                    penalty += 0.15
                if d >= 3 and cheby <= d:
                    bonus += 0.05

            new_p = current_p + penalty - bonus
            new_p = max(0.01, min(0.99, new_p))
            updated[pos] = new_p

        return updated

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        min_dist = None
        for nr in range(rows):
            for nc in range(cols):
                cell = grid[nr][nc]
                if cell.is_revealed and not cell.is_mine:
                    d = cell.adjacent_mines
                    cheby = max(abs(r - nr), abs(c - nc))
                    if d >= 3 and (min_dist is None or cheby < min_dist):
                        min_dist = cheby

        safety_bonus = 0.0
        if min_dist is not None and min_dist >= 3:
            safety_bonus = -0.1

        return (p + safety_bonus, self._rng.random())

