class RingCountInfo(InfoStrategy):
    """
    Each revealed cell shows TWO numbers: the count of mines among the 4 cardinal
    neighbors (N/S/E/W, ring-1 orthogonal) and the count of mines among the 4
    diagonal neighbors (NE/NW/SE/SW, ring-1 diagonal), displayed as 'C|D'.
    This gives skilled solvers two independent additive constraints per cell —
    the cardinal count pins mines to cross-shaped positions while the diagonal
    count pins mines to X-shaped positions, enabling precise triangulation that
    random play cannot exploit.
    """

    def encode(self, board, r, c):
        cardinal = 0
        diagonal = 0
        for nr, nc in board.neighbors(r, c):
            if not board.grid[nr][nc].is_mine:
                continue
            dr = nr - r
            dc = nc - c
            if dr == 0 or dc == 0:
                cardinal += 1
            else:
                diagonal += 1
        total = cardinal + diagonal
        if total == 0:
            return ""
        return str(cardinal) + "|" + str(diagonal)

