class DualChannelRingCountAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed or cell.is_mine:
            return None
        raw = str(cell.adjacent_mines) if cell.adjacent_mines is not None else ""
        if "|" in raw:
            parts = raw.split("|")
            try:
                return int(parts[0]) + int(parts[1])
            except (ValueError, IndexError):
                return None
        try:
            return int(raw)
        except (ValueError, TypeError):
            return None

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        cardinal_dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        diagonal_dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if not cell.is_revealed or cell.is_mine:
                    continue
                raw = str(cell.adjacent_mines) if cell.adjacent_mines is not None else ""
                if "|" not in raw:
                    continue
                parts = raw.split("|")
                try:
                    card_count = int(parts[0])
                    diag_count = int(parts[1])
                except (ValueError, IndexError):
                    continue

                card_neighbors = []
                diag_neighbors = []
                for dr, dc in cardinal_dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        card_neighbors.append((nr, nc))
                for dr, dc in diagonal_dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        diag_neighbors.append((nr, nc))

                card_flagged = sum(1 for pos in card_neighbors if pos in mine_set)
                diag_flagged = sum(1 for pos in diag_neighbors if pos in mine_set)
                card_unknown = [pos for pos in card_neighbors if pos not in mine_set and not game.get_cell(pos[0], pos[1]).is_revealed]
                diag_unknown = [pos for pos in diag_neighbors if pos not in mine_set and not game.get_cell(pos[0], pos[1]).is_revealed]

                card_remaining = card_count - card_flagged
                diag_remaining = diag_count - diag_flagged

                if card_remaining >= 0 and len(card_unknown) > 0:
                    if card_remaining == 0:
                        for pos in card_unknown:
                            if pos in prob_map:
                                prob_map[pos] = min(prob_map[pos], 0.05)
                    elif card_remaining == len(card_unknown):
                        for pos in card_unknown:
                            mine_set.add(pos)
                            prob_map[pos] = 1.0
                    else:
                        p = card_remaining / len(card_unknown)
                        for pos in card_unknown:
                            if pos in prob_map:
                                prob_map[pos] = (prob_map[pos] + p) / 2.0

                if diag_remaining >= 0 and len(diag_unknown) > 0:
                    if diag_remaining == 0:
                        for pos in diag_unknown:
                            if pos in prob_map:
                                prob_map[pos] = min(prob_map[pos], 0.05)
                    elif diag_remaining == len(diag_unknown):
                        for pos in diag_unknown:
                            mine_set.add(pos)
                            prob_map[pos] = 1.0
                    else:
                        p = diag_remaining / len(diag_unknown)
                        for pos in diag_unknown:
                            if pos in prob_map:
                                prob_map[pos] = (prob_map[pos] + p) / 2.0

        return prob_map

