class ExtendedCrossNeighborhoodAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        offsets = [(-2, 0), (-1, 0), (1, 0), (2, 0), (0, -2), (0, -1), (0, 1), (0, 2)]
        result = []
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc))
        return result

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        neighbors = self.neighbor_positions(game, r, c, rows, cols)
        revealed_neighbors = [
            (nr, nc) for nr, nc in neighbors
            if grid[nr][nc].is_revealed and not grid[nr][nc].is_mine
        ]
        if not revealed_neighbors:
            return cell.adjacent_mines
        neighbor_counts = [grid[nr][nc].adjacent_mines for nr, nc in revealed_neighbors]
        my_count = cell.adjacent_mines
        all_vals = neighbor_counts + [my_count]
        sorted_unique = sorted(set(all_vals))
        rank = sorted_unique.index(my_count) + 1
        if len(sorted_unique) == 1:
            return my_count
        anchor_candidates = [
            (nr, nc) for nr, nc in revealed_neighbors
            if not [
                (nnr, nnc) for nnr, nnc in self.neighbor_positions(game, nr, nc, rows, cols)
                if grid[nnr][nnc].is_revealed and not grid[nnr][nnc].is_mine
            ]
        ]
        if anchor_candidates:
            anchor_r, anchor_c = anchor_candidates[0]
            anchor_true = grid[anchor_r][anchor_c].adjacent_mines
            anchor_neighbor_counts = [grid[nr][nc].adjacent_mines for nr, nc in self.neighbor_positions(game, anchor_r, anchor_c, rows, cols) if grid[nr][nc].is_revealed and not grid[nr][nc].is_mine]
            if not anchor_neighbor_counts:
                anchor_rank = 1
            else:
                anchor_all = anchor_neighbor_counts + [anchor_true]
                anchor_sorted = sorted(set(anchor_all))
                anchor_rank = anchor_sorted.index(anchor_true) + 1
            rank_delta = rank - anchor_rank
            return max(0, anchor_true + rank_delta)
        return my_count

class NoisyCountMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        unrevealed_frontier = set()
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed and not cell.is_mine:
                    for nr, nc in neighbors_of.get((r, c), []):
                        ncell = grid[nr][nc]
                        if not ncell.is_revealed and not ncell.is_flagged:
                            unrevealed_frontier.add((nr, nc))

        definite_mines = set()
        definite_safe = set()

        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                true_count = cell.adjacent_mines
                neighbors = neighbors_of.get((r, c), [])
                unrevealed = [(nr, nc) for nr, nc in neighbors
                              if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged]
                flagged = sum(1 for nr, nc in neighbors if grid[nr][nc].is_flagged)
                already_mined = sum(1 for nr, nc in neighbors if (nr, nc) in mine_set)
                effective_flagged = flagged + already_mined
                remaining_unrevealed = len(unrevealed)

                for delta in (-1, 0, 1):
                    noisy_count = true_count + delta
                    remaining_mines = noisy_count - effective_flagged
                    if remaining_mines < 0 or remaining_mines > remaining_unrevealed:
                        continue
                    if remaining_mines == remaining_unrevealed and remaining_unrevealed > 0:
                        pass
                    if remaining_mines == 0 and remaining_unrevealed > 0:
                        pass

                all_deltas_mine = True
                all_deltas_safe = True

                for delta in (-1, 0, 1):
                    noisy_count = true_count + delta
                    remaining_mines = noisy_count - effective_flagged
                    if remaining_mines < 0 or remaining_mines > remaining_unrevealed:
                        continue
                    if not (remaining_mines == remaining_unrevealed and remaining_unrevealed > 0):
                        all_deltas_mine = False
                    if not (remaining_mines == 0 and remaining_unrevealed > 0):
                        all_deltas_safe = False

                if all_deltas_mine and remaining_unrevealed > 0:
                    valid = True
                    for delta in (-1, 0, 1):
                        noisy_count = true_count + delta
                        rm = noisy_count - effective_flagged
                        if 0 <= rm <= remaining_unrevealed:
                            if rm != remaining_unrevealed:
                                valid = False
                                break
                    if valid:
                        for pos in unrevealed:
                            definite_mines.add(pos)

                if all_deltas_safe and remaining_unrevealed > 0:
                    valid = True
                    for delta in (-1, 0, 1):
                        noisy_count = true_count + delta
                        rm = noisy_count - effective_flagged
                        if 0 <= rm <= remaining_unrevealed:
                            if rm != 0:
                                valid = False
                                break
                    if valid:
                        for pos in unrevealed:
                            definite_safe.add(pos)

        new_prob_map = dict(prob_map)
        for pos in definite_mines:
            if pos not in mine_set:
                new_prob_map[pos] = 1.0
        for pos in definite_safe:
            if pos not in mine_set:
                new_prob_map[pos] = 0.0

        for pos in unrevealed_frontier:
            if pos not in definite_mines and pos not in definite_safe:
                if pos in new_prob_map:
                    p = new_prob_map[pos]
                    shrunk = 0.5 + (p - 0.5) * 0.7
                    new_prob_map[pos] = max(0.05, min(0.95, shrunk))

        return new_prob_map

