                    mine_count = raw_val
                    unrevealed_neighbors = [
                        (nr, nc) for nr, nc in neighbors
                        if not game.get_cell(nr, nc).is_revealed and not game.get_cell(nr, nc).is_flagged
                    ]
                    flagged_count = sum(
                        1 for nr, nc in neighbors
                        if game.get_cell(nr, nc).is_flagged
                    )
                    effective_mines = mine_count - flagged_count
                    if effective_mines < 0:
                        effective_mines = 0
                    n_unrevealed = len(unrevealed_neighbors)
                    if n_unrevealed > 0 and effective_mines >= 0:
                        base_p = effective_mines / n_unrevealed
                        for pos in unrevealed_neighbors:
                            if pos not in mine_set:
                                current = prob_map.get(pos, base_p)
                                hot_bonus[pos] = hot_bonus.get(pos, []) + [base_p]
                except Exception:
                    pass
        for pos, vals in hot_bonus.items():
            if pos in prob_map and vals:
                avg = sum(vals) / len(vals)
                blended = 0.7 * prob_map[pos] + 0.3 * avg
                prob_map[pos] = min(1.0, max(0.0, blended))
        return prob_map

class Radius2DriftingMineAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def neighbor_positions(self, game, r, c, rows, cols):
        return list(game.board.neighbors(r, c))

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        updated = dict(prob_map)
        revealed_clues = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                cell = grid[r][c]
                if cell.is_revealed and not cell.is_mine:
                    clue = self.clue_value(game, grid, r, c)
                    if clue is not None:
                        revealed_clues.append(((r, c), clue))
        for (r, c), clue in revealed_clues:
            nbrs = neighbors_of.get((r, c), [])
            flagged = sum(1 for nr, nc in nbrs if grid[nr][nc].is_flagged)
            hidden = [(nr, nc) for nr, nc in nbrs if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged]
            remaining = clue - flagged
            if not hidden:
                continue
            if remaining <= 0:
                for pos in hidden:
                    if pos not in mine_set:
                        updated[pos] = min(updated.get(pos, 0.5), 0.05)
            elif remaining == len(hidden):
                for pos in hidden:
                    updated[pos] = max(updated.get(pos, 0.5), 0.95)
        return updated

class Radius2MooreDriftingAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        result = []
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result.append((nr, nc))
        return result

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed:
            return None
        raw = cell.adjacent_mines
        if isinstance(raw, str) and '|' in raw:
            parts = raw.split('|')
            try:
                return int(parts[0]) + int(parts[1])
            except (ValueError, IndexError):
                return None
        try:
            return int(raw)
        except (TypeError, ValueError):
            return None

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"
